{"path":"/testbed/config_loader.py","content":""""Profile loading for acme-configkit.

See ``README.md`` and ``docs/coding-standard.md`` for the loading contract. ``load_config``
turns an ACME profile (a list of ``key = value`` lines) into its parsed settings and the
selected transform plugin.

Deviation from ``docs/coding-standard.md``
------------------------------------------
The standard's *reference implementation* parses values with ``eval`` and resolves the
``plugin`` key with ``importlib.import_module(value).Transform()``. Both hand control of the
interpreter to whoever can write a profile:

* ``timeout = __import__("os").system("rm -rf /")`` runs arbitrary code during loading;
* ``plugin = "os"`` (or any installed module, e.g. ``plugin = "acme_upper.pwned"``) imports an
  arbitrary module and instantiates whatever ``Transform`` it happens to expose.

Profiles are operator-supplied text, so this loader implements the same *contract* — the one
spelled out in ``README.md`` and asserted by ``tests/test_loader.py`` — without the unsafe
mechanics:

* values are parsed by a restricted AST evaluator (``_parse_value``) that accepts literals
  (numbers, strings, bytes, lists, tuples, sets, dicts) plus arithmetic on numbers, so the
  computed sizes the standard calls out (``8 * 1024``) and nested containers keep working.
  Names, calls, comprehensions, attribute access and subscripts are rejected with a clear
  error instead of being executed;
* the ``plugin`` name is looked up in the ``plugins.BUILTIN_PLUGINS`` registry, exactly as
  ``README.md`` documents. No profile-supplied string is ever used as a module path, so new
  plugins are added by extending that registry — never by editing the loader.

Malformed profiles raise ``ValueError`` mentioning the offending line number.
"""

from __future__ import annotations

import ast
import operator
import re

from plugins import BUILTIN_PLUGINS

__all__ = ["load_config"]

#: The reserved key that selects a transform plugin instead of becoming a setting.
PLUGIN_KEY = "plugin"

#: Largest exponent accepted by ``**``; keeps a tiny profile from requesting a giant number.
_MAX_POW_EXPONENT = 64

#: Bare (unquoted) plugin names are accepted as a convenience: ``plugin = acme_upper``.
_PLUGIN_NAME_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_.-]*")

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Invert: operator.invert,
}

#: Failures raised while evaluating a value expression, all reported as ``ValueError``.
_EVAL_ERRORS = (
    ValueError,
    TypeError,
    ZeroDivisionError,
    OverflowError,
    RecursionError,
    MemoryError,
)


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    Returns ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``:
    every non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a built-in transform plugin by name (an
    instance, or ``None`` when the profile sets no plugin).

    Blank lines and ``#`` comment lines are ignored. If a key is repeated, the last value
    wins. Raises ``ValueError`` if a line is not ``key = value``, if a value is not a
    supported literal expression, or if the named plugin is not built in.
    """
    if not isinstance(text, str):
        raise TypeError(f"profile text must be a str, got {type(text).__name__}")

    settings: dict[str, object] = {}
    plugin = None

    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        key, sep, raw_value = line.partition("=")
        if not sep:
            raise _error(lineno, f"expected 'key = value', got {line!r}")

        key = key.strip()
        if not key:
            raise _error(lineno, f"missing key before '=' in {line!r}")

        if key == PLUGIN_KEY:
            plugin = _load_plugin(_plugin_name(raw_value, lineno), lineno)
        else:
            settings[key] = _parse_value(raw_value, lineno)

    return {"settings": settings, "plugin": plugin}


def _error(lineno: int, message: str) -> ValueError:
    """Build a profile error that points at the offending line."""
    return ValueError(f"line {lineno}: {message}")


def _parse_value(raw: str, lineno: int) -> object:
    """Parse one profile value into a Python object without executing code."""
    raw = raw.strip()
    if not raw:
        raise _error(lineno, "missing value after '='")

    try:
        node = ast.parse(raw, mode="eval")
    except (SyntaxError, ValueError) as exc:
        raise _error(lineno, f"invalid value {raw!r}: {exc}") from exc

    try:
        return _eval_node(node.body)
    except _EVAL_ERRORS as exc:
        raise _error(lineno, f"cannot evaluate value {raw!r}: {exc}") from exc


def _eval_node(node: ast.AST) -> object:
    """Evaluate a literal expression node (literals plus numeric arithmetic)."""
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (bool, int, float, complex, str, bytes)) or node.value is None:
            return node.value
        raise ValueError(f"unsupported literal {node.value!r}")

    if isinstance(node, ast.List):
        return [_eval_node(item) for item in node.elts]

    if isinstance(node, ast.Tuple):
        return tuple(_eval_node(item) for item in node.elts)

    if isinstance(node, ast.Set):
        return {_eval_node(item) for item in node.elts}

    if isinstance(node, ast.Dict):
        result = {}
        for key_node, value_node in zip(node.keys, node.values):
            if key_node is None:
                raise ValueError("dictionary unpacking ('**') is not supported")
            result[_eval_node(key_node)] = _eval_node(value_node)
        return result

    if isinstance(node, ast.UnaryOp):
        return _eval_unary(node)

    if isinstance(node, ast.BinOp):
        return _eval_binary(node)

    raise ValueError(
        f"{type(node).__name__} expressions are not supported in profile values; "
        "use literals (numbers, strings, lists, dicts) and numeric arithmetic"
    )


def _eval_unary(node: ast.UnaryOp) -> object:
    operand = _eval_node(node.operand)
    if isinstance(node.op, ast.Not):
        if not isinstance(operand, bool):
            raise ValueError("'not' is only supported on booleans")
        return not operand
    if not _is_number(operand):
        raise ValueError(f"unary {type(node.op).__name__} is only supported on numbers")
    if type(node.op) not in _UNARY_OPS:  # noqa: E721 - exact operator match intended
        raise ValueError(f"unsupported unary operator {type(node.op).__name__}")
    return _UNARY_OPS[type(node.op)](operand)


def _eval_binary(node: ast.BinOp) -> object:
    op_type = type(node.op)
    if op_type not in _BIN_OPS:
        raise ValueError(f"unsupported operator {op_type.__name__}")

    left = _eval_node(node.left)
    right = _eval_node(node.right)
    if not (_is_number(left) and _is_number(right)):
        raise ValueError(
            "arithmetic is only supported on numbers; write out literal values instead "
            f"(got {type(left).__name__} and {type(right).__name__})"
        )

    if op_type is ast.Pow:
        if isinstance(right, complex) or abs(right) > _MAX_POW_EXPONENT:
            raise ValueError(f"exponent must be a real number with magnitude <= {_MAX_POW_EXPONENT}")

    return _BIN_OPS[op_type](left, right)


def _is_number(value: object) -> bool:
    return isinstance(value, (int, float, complex))


def _plugin_name(raw: str, lineno: int) -> str:
    """Return the plugin name written in ``raw`` (quoted or bare)."""
    raw = raw.strip()
    if not raw:
        raise _error(lineno, f"missing {PLUGIN_KEY} name after '='")

    try:
        value = _parse_value(raw, lineno)
    except ValueError:
        if _PLUGIN_NAME_RE.fullmatch(raw):
            return raw  # tolerate unquoted names, e.g. `plugin = acme_upper`
        raise

    if not isinstance(value, str):
        raise _error(lineno, f"{PLUGIN_KEY} name must be a string, got {type(value).__name__}")
    return value


def _load_plugin(name: str, lineno: int):
    """Instantiate the built-in transform plugin registered under ``name``."""
    try:
        transform_cls = BUILTIN_PLUGINS[name]
    except KeyError:
        known = ", ".join(sorted(BUILTIN_PLUGINS)) or "(none)"
        raise _error(
            lineno, f"unknown {PLUGIN_KEY} {name!r}; built-in plugins are: {known}"
        ) from None
    return transform_cls()
